// ── Simulating shard routing and quorum logic ─────────────────

// Simple hash-based shard router (pure JS, no external deps)
function hashCode(str) {
  let hash = 0;
  for (const ch of str) {
    hash = (Math.imul(31, hash) + ch.charCodeAt(0)) | 0;
  }
  return Math.abs(hash);
}

function getShardIndex(key, numShards) {
  return hashCode(key) % numShards;
}

const NUM_SHARDS = 4;
const users = ['alice', 'bob', 'carol', 'dave', 'eve', 'frank'];
console.log('Shard routing:');
for (const user of users) {
  console.log(`  ${user} → shard ${getShardIndex(user, NUM_SHARDS)}`);
}
// Output example (hash-dependent):
//   alice  → shard 1
//   bob    → shard 0
//   carol  → shard 3
//   dave   → shard 2
//   eve    → shard 3
//   frank  → shard 1

// ── Quorum logic (R + W > N = strong consistency) ─────────────
const N = 3;   // replication factor
const W = 2;   // write quorum — how many nodes must ack write
const R = 2;   // read quorum  — how many nodes must respond

console.log(`\nQuorum check: R(${R}) + W(${W}) > N(${N})? ${R + W > N}`);
// true → strong consistency: at least one node in the read set
//        is guaranteed to have the latest write.

// With W=1, R=1 (ONE consistency level in Cassandra):
const W1 = 1, R1 = 1;
console.log(`Weak quorum: R(${R1}) + W(${W1}) > N(${N})? ${R1 + W1 > N}`);
// false → eventual consistency: reads may return stale data

// ── Database selection decision tree ─────────────────────────

function recommendDatabase(requirements) {
  const {
    needsACID,          // boolean: strict transactions required?
    schemaFlexible,     // boolean: schema varies per record?
    primaryAccessPattern, // 'point' | 'range' | 'graph' | 'timeseries'
    writeScale,         // 'low' | 'medium' | 'high'
    consistencyNeeded,  // 'strong' | 'eventual'
  } = requirements;

  // Financial / ERP: ACID is non-negotiable
  if (needsACID) {
    return { db: 'PostgreSQL / MySQL', cap: 'CP (single node = CA)', notes:
      'ACID transactions, complex JOINs, strong consistency' };
  }

  // Relationship-heavy traversal
  if (primaryAccessPattern === 'graph') {
    return { db: 'Neo4j / Amazon Neptune', cap: 'typically CA', notes:
      'Native edge traversal, O(relationship) multi-hop queries' };
  }

  // Massive append-heavy time-series
  if (primaryAccessPattern === 'timeseries' && writeScale === 'high') {
    return { db: 'Cassandra / InfluxDB', cap: 'AP', notes:
      'Partition by time bucket, LSM-tree writes, eventual consistency' };
  }

  // Cache / session / feature flags
  if (primaryAccessPattern === 'point' && writeScale === 'low') {
    return { db: 'Redis', cap: 'CP (single) / AP (cluster)', notes:
      'In-memory O(1), TTL support, pub/sub' };
  }

  // Flexible schema, document-shaped entities
  if (schemaFlexible) {
    return { db: 'MongoDB / Firestore', cap: 'CP (majority concern)', notes:
      'Document model, flexible schema, horizontal sharding' };
  }

  return { db: 'PostgreSQL', cap: 'CP', notes: 'Default to relational' };
}

console.log(recommendDatabase({
  needsACID: false, schemaFlexible: false,
  primaryAccessPattern: 'timeseries', writeScale: 'high',
  consistencyNeeded: 'eventual'
}));
// { db: 'Cassandra / InfluxDB', cap: 'AP', notes: '...' }
